"""Build the self-contained Colab notebook from the actual app, never a second code copy.

Run `python scripts/build_notebook.py` after changing app sources or web assets.
CI can use `python scripts/build_notebook.py --check` to reject stale bundles.
"""

import argparse
import base64
import hashlib
import io
import json
import shlex
import textwrap
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
FILES = [
    "solvra_app.py",
    "solvra_assistant.py",
    "solvra_ai.py",
    "solvra_insights.py",
    "solvra_profiles.py",
    "solvra_workspace.py",
    "solvra_voice.py",
    "solvra_speech.py",
    "licenses/KOKORO.txt",
    "licenses/PUTER.txt",
    "web/index.html",
    "web/styles.css",
    "web/app.js",
    "web/ai.js",
    "web/vendor/puter-2.6.5.js",
    "web/vendor/README.md",
    "web/speech.js",
    "web/voice.js",
    "web/dm-sans-latin.woff2",
    "web/FONT-LICENSE.txt",
]


def cell(kind, text, name, collapsed=False):
    result = {
        "cell_type": kind,
        "id": hashlib.sha256(name.encode()).hexdigest()[:8],
        "metadata": {},
        "source": text.splitlines(keepends=True),
    }
    if kind == "code":
        result.update({"execution_count": None, "outputs": []})
        if collapsed:
            result["metadata"] = {"cellView": "form"}
    return result


def build():
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for name in FILES:
            info = zipfile.ZipInfo(name, date_time=(2026, 11, 14, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            archive.writestr(info, (ROOT / name).read_bytes())
    bundle = buffer.getvalue()
    encoded = "\n".join(textwrap.wrap(base64.b85encode(bundle).decode(), width=100))
    requirements = [
        line.strip()
        for line in (ROOT / "requirements.txt").read_text().splitlines()
        if line.strip() and not line.startswith(("#", "pytest"))
    ]
    bootstrap = (
        '''# @title Load the complete workspace (embedded source + local assets)
# This bundle is generated by scripts/build_notebook.py from the repository.
# Recognition works offline; natural read-aloud caches its model on first use.
import base64
import hashlib
import io
import shutil
import sys
import zipfile
from pathlib import Path

_bundle = base64.b85decode("""\n'''
        + encoded
        + '''\n""".replace("\\n", ""))
if hashlib.sha256(_bundle).hexdigest() != "'''
        + hashlib.sha256(bundle).hexdigest()
        + """":
    raise RuntimeError("The embedded workspace is incomplete. Download the notebook again.")
# Keep the embedded frontend next to the notebook runtime instead of in /tmp.
# Notebook providers can clean temporary directories while a server is still
# running, which leaves an imported solvra_app module unable to find web assets.
_solvra_root = (Path.cwd() / ".solvra-workspace").resolve()
if _solvra_root.exists():
    shutil.rmtree(_solvra_root)
_solvra_root.mkdir(parents=True, exist_ok=True)
with zipfile.ZipFile(io.BytesIO(_bundle)) as archive:
    for name in archive.namelist():
        target = (_solvra_root / name).resolve()
        if _solvra_root.resolve() not in target.parents:
            raise RuntimeError("Unsafe bundle path")
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(archive.read(name))
sys.path.insert(0, str(_solvra_root))
print("Workspace source and local assets are ready.")
"""
    )
    cells = [
        cell(
            "markdown",
            "# Solvra — your money, in focus\n\nA complete financial workspace: cash-flow charts, searchable transactions, an explainable bill planner, account-grounded chat, and voice with live captions and an offline fallback.\n\n**Four fictional households · snapshot November 14, 2026 · not financial advice.** No bank is connected and no money is moved.\n\nRun the four cells below in order. No paid API key is required. Offline recognition is bundled; natural neural read-aloud downloads about 90 MB of verified model assets on first use. This notebook embeds the exact Python and frontend sources from the repository; it does not fetch an older copy from `main`.\n",
            "intro",
        ),
        cell(
            "markdown",
            "## 1 · Install\n\nPocketSphinx includes an offline English recognition model. Live captions use your browser speech service. Kokoro provides local neural read-aloud; its verified model is cached on first read-aloud (about 90 MB).\n",
            "install-info",
        ),
        cell(
            "code",
            "%pip install -q " + " ".join(shlex.quote(r) for r in requirements) + "\n",
            "install",
        ),
        cell(
            "markdown",
            "## 2 · Load the workspace\n\nThe collapsed cell unpacks the app, voice controller, local font, and interface. Developers should edit the repository files and regenerate this notebook with `python scripts/build_notebook.py`.\n",
            "bundle-info",
        ),
        cell("code", bootstrap, "bundle", True),
        cell("markdown", "## 3 · Check the four demo scenarios\n", "check-info"),
        cell(
            "code",
            "import solvra_app as solvra\nfrom solvra_profiles import PEOPLE, DemoAccount\nfrom solvra_insights import financial_trouble\n\nfor profile_id in PEOPLE:\n    account = DemoAccount(profile_id)\n    trouble = financial_trouble(account)\n    assert len(account.transactions) >= 200\n    print(f\"{account.profile['name']}: {len(account.transactions)} entries, checking ${account.balance('Checking'):,.2f}, {trouble['label']} ({trouble['score']}/100 pressure points)\")\n",
            "check",
        ),
        cell(
            "markdown",
            "## 4 · Open Solvra\n\nOpen the public **HTTPS** link printed below in its **own browser tab**, not the embedded Colab frame. Keep the runtime running. Choose Maya, Jordan, Aisha or Marcus at the clearly labeled simulated login, then select **Log in to demo**. Each has a distinct in-memory financial scenario. Use **Settings → Log out** to choose someone else. No real credentials are needed.\n",
            "launch-info",
        ),
        cell("code", "solvra.main()\n", "launch"),
        cell(
            "markdown",
            "## Make it useful\n\n- **Demo login:** Maya is Stable, Jordan is Watch, Aisha is High, and Marcus is Critical in the starting financial-trouble ranking. These are different ledgers, not renamed copies. Logout in Settings cancels pending changes, clears the visible account, stops voice and disconnects AI; confirmed changes and chat stay separate per person in this tab while the runtime lives. Reset restores only the selected person. This is not secure authentication.\n- **Overview:** compare income and spending; see category totals and upcoming bills. November is a partial month, clearly marked.\n- **Transactions:** search merchants, filter by date/category/account, inspect a record, export CSV, or add a transaction after confirmation.\n- **Bills & payments:** choose a reserve and calculate a payment preview. Expected income is excluded unless explicitly included. Try a late-payment what-if without changing the due date.\n- **Insights:** inspect the financial-trouble ranking, thresholds, safety floors and all six factors. Higher pressure points mean greater urgency; priority 1 is most urgent. This is not a credit score or a default/eviction prediction. Ask “Explain my financial trouble ranking and what I should do first.” Grok receives this selected person’s exact assessment after consent, never other people’s finances. Also inspect the separate seven-factor health model and ask a follow-up. Comparisons use like-for-like reporting windows.\n- **Assistant:** try “Can I afford a $200 purchase?”, “Compare my grocery spending this month with the previous period”, or “What if my paycheck is 5 days late?”. Connect Grok AI in the assistant panel for broad finance-only guidance. Puter sign-in and explicit data-sharing consent are required; your own Puter allowance covers usage and may have limits or charges. Only the selected person’s profile, financial summaries, financial-trouble assessment, relevant calculations and recent finance conversation are shared with Puter / the model provider. Without connection, local calculations and confirmations remain available.\n\n### Voice in one clean turn\n\n1. Tap **Ask by voice** in the assistant composer and allow microphone access. Speaking stays in the composer; it does not open a separate voice popup.\n2. Browser recognition waits for a final result, removes repeated phrases, then processes and sends one clean question automatically. Where browser support exists, finance, account, bill, and selected-person phrase bias improves recognition of terms such as checking, savings, and payment plan.\n3. If browser recognition is unreachable, the app records locally, processes the completed transcript, and sends it in that same flow.\n4. Use **Test microphone only**, select an input, or upload a recording (maximum 45 seconds / 15 MB).\n5. If permission is blocked in Colab's frame, use the public HTTPS link in a new tab and allow the microphone there.\n6. In voice settings, preview a natural speaking voice and choose a pace. Kokoro neural read-aloud runs on this server, not an external speech API; Device voice is an explicit fallback.\n\nBrowser speech recognition may use your browser provider's speech service. Offline recordings are uploaded to the app server for transcription. Account changes always require a separate confirmation, regardless of voice mode.\n\n### Session limits\n\nDemo workspace changes last while the server runs (up to eight hours of inactivity, with capacity eviction possible). They are not a permanent database. Reset affects only the selected person; logout revokes the active token but retains that person’s confirmed demo changes and conversation separately for re-entry. For a live demo, test Preview voice, the actual physical microphone and your own Puter sign-in/allowance before presenting. External services and browser permissions are not guaranteed. Do not enter real bank credentials or sensitive financial information.\n",
            "guide",
        ),
    ]
    notebook = {
        "cells": cells,
        "metadata": {
            "kernelspec": {
                "display_name": "Python 3",
                "language": "python",
                "name": "python3",
            },
            "language_info": {"name": "python"},
            "colab": {"name": "Solvra_Financial_Triage.ipynb", "provenance": []},
        },
        "nbformat": 4,
        "nbformat_minor": 5,
    }
    return json.dumps(notebook, indent=1, ensure_ascii=False) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    target = ROOT / "Solvra_Financial_Triage.ipynb"
    content = build()
    if args.check:
        if target.read_text() != content:
            raise SystemExit("Notebook bundle is stale. Run python scripts/build_notebook.py")
        print("Notebook bundle matches app sources and assets.")
    else:
        target.write_text(content)
        print(f"Updated {target.name} ({len(content):,} characters)")


if __name__ == "__main__":
    main()
